<script lang="ts">
import { defineComponent, ref } from 'vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import Vue3DraggableResizable from 'vue3-draggable-resizable';
import 'vue3-draggable-resizable/dist/Vue3DraggableResizable.css';
import { DraggableContainer } from 'vue3-draggable-resizable';
import LineItemsVue from '../PurchaseOrders/LineItems.vue';

export default defineComponent({
  components: {
    Vue3DraggableResizable,
    DraggableContainer,
    SubHeader,
  },
  methods: {
    print(val: any) {
      logInfo(val);
    },
  },
  mounted() {
    document.addEventListener('keydown', this.onKeyDown);
  },
  beforeMount() {
    document.removeEventListener('keydown', this.onKeyDown);
  },
  setup() {
    const items = ref<any[]>([]);
    const imageUpload = ref<any>('');
    const bar = ref(false);
    const Type = ref('new');
    const TypeContent = ref('text');
    const editType = ref('');
    const colorFace = ref<any>('');
    const menuFormat = ref(false);
    const menuTextSizeFormat = ref(false);
    const checkbox = ref(false);
    const ClearConfirm = ref(false);
    const SaveTemplate = ref(false);
    const IdActive = ref<any>(null);
    const ImageUrl = ref<string>('');
    const TableContent = ref<any>({
      header: <any[]>[],
      data: <any[]>[],
    });
    const textEdit = ref({
      id: 0,
      content: 'text',
      title: 'undefine',
      label: '',
      child: <any>{},
      styles: {
        bold: false,
        underline: false,
        color: '',
        bgColor: '',
        textSize: '',
        ZIndex: 1,
      },
    });
    const headingOptions = ref([
      { label: 'H1', size: '2em' },
      { label: 'H2', size: '1.5em' },
      { label: 'H3', size: '1.17em' },
      { label: 'H4', size: '1em' },
      { label: 'H5', size: '0.83em' },
      { label: 'H6', size: '0.67em' },
    ]);

    const addTable = (type: string, item: any = null) => {
      switch (type) {
        case 'header': {
          TableContent.value.header.push({
            label: '',
          });
          break;
        }
        case 'data': {
          const data: any = {};
          TableContent.value.header.forEach(
            (head: any) => (data[head.label] = ''),
          );
          TableContent.value.data.push(data);
          break;
        }
      }
    };

    const onFormatClick = (size: string) => {
      //
    };

    const clearData = () => {
      localStorage.removeItem('items');
      window.location.reload();
    };

    const addItem = () => {
      let maxId = 0;
      for (const item of items.value) {
        if (item.id > maxId) {
          maxId = item.id;
        }
      }
      // Increment maxId by 1 for the new item
      const newId = maxId + 1;

      return newId;
    };
    const ChangeZIndexItem = () => {
      let maxIndex = 0;
      for (const item of items.value) {
        if (item.styles.ZIndex > maxIndex) {
          maxIndex = item.styles.ZIndex;
        }
      }
      // Increment maxIndex by 1 for the new item
      const newIndex = maxIndex + 1;

      return newIndex;
    };

    const closeEditor = () => {
      Type.value = 'new';
      return (bar.value = !bar.value);
    };
    function applyStyles(type: string, value: any = null) {
      const textElement: any = document.getElementById('text');
      switch (type) {
        case 'bold': {
          textEdit.value.styles.bold = !textEdit.value.styles.bold;
          textElement.style.fontWeight = textEdit.value.styles.bold
            ? '900'
            : '900';
          break;
        }
        case 'underline': {
          textEdit.value.styles.underline = !textEdit.value.styles.underline;
          textElement.style.textDecoration = textEdit.value.styles.underline
            ? 'underline'
            : 'none';
          break;
        }
        case 'color': {
          textElement.style.color = textEdit.value.styles.color;
          break;
        }
        case 'bgColor': {
          textElement.style.background = textEdit.value.styles.bgColor;
          break;
        }
        case 'textSize': {
          textEdit.value.styles.textSize = value;
          textElement.style.fontSize = textEdit.value.styles.textSize;
          break;
        }
        case 'ZIndex': {
          textEdit.value.styles.ZIndex = ChangeZIndexItem();
          textElement.style.ZIndex = textEdit.value.styles.ZIndex;
          break;
        }
      }
    }

    const renderStyle = (item: any) => {
      let styleObj = {};
      if (item.styles) {
        styleObj = {
          fontWeight: item.styles.bold ? 'bold' : 'normal',
          textDecoration: item.styles.underline ? 'underline' : 'none',
          color: item.styles.color || 'inherit',
          backgroundColor: item.styles.bgColor || 'transparent',
          fontSize: item.styles.textSize || 'inherit',
          zIndex: item.styles.ZIndex || 1,
        };
      }

      return styleObj;
    };

    const AddMore = (type: string) => {
      switch (type) {
        case 'text': {
          TypeContent.value = 'text';
          textEdit.value.content = 'text';
          textEdit.value.label = '';
          textEdit.value.id = items.value.length + 1;
          break;
        }
        case 'image': {
          TypeContent.value = 'image';
          textEdit.value.content = 'image';
          textEdit.value.label = '';
          textEdit.value.id = items.value.length + 1;
          break;
        }
        case 'div': {
          TypeContent.value = 'div';
          textEdit.value.content = 'div';
          textEdit.value.label = '';
          textEdit.value.id = items.value.length + 1;
          break;
        }
        case 'form': {
          TypeContent.value = 'form';
          textEdit.value.content = 'form';
          textEdit.value.label = '';
          textEdit.value.id = items.value.length + 1;
          break;
        }
        case 'table': {
          TypeContent.value = 'table';
          textEdit.value.content = 'table';
          textEdit.value.label = '';
          textEdit.value.child = { header: [], data: [] };
          textEdit.value.id = items.value.length + 1;
          break;
        }
      }
      bar.value = !bar.value;
    };
    const AddImage = () => {
      TypeContent.value = 'image';
      textEdit.value.content = 'image';
      textEdit.value.label = '';
      textEdit.value.child = { header: [], data: [] };
      textEdit.value.id = items.value.length + 1;
      bar.value = !bar.value;
    };
    let newItem = localStorage.getItem('items');
    if (newItem) {
      items.value = JSON.parse(newItem);
    }

    const onResize = (index: number, event: any) => {
